<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Niveaux et classes — Clarodaro</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#1e293b;font:16px Arial,sans-serif}header{background:#12355b;color:#fff;text-align:center;padding:20px}header h1{margin:0 0 6px}nav{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;padding:12px;background:#fff;border-bottom:1px solid #dbe2ea}nav button{border:0;border-radius:7px;padding:10px 14px;background:#e8eef6;color:#12355b;font-weight:bold;cursor:pointer}.container{max-width:1150px;margin:24px auto;padding:0 14px}.card{background:#fff;border:1px solid #dce4ee;border-radius:12px;padding:20px;margin-bottom:18px;box-shadow:0 2px 8px #12355b0b}h2{margin:0 0 14px;color:#12355b}.form{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;align-items:end}.field{display:grid;gap:6px;font-weight:bold}.field input,.field select{width:100%;min-height:42px;padding:9px;border:1px solid #b8c5d4;border-radius:7px;font:inherit}.btn{border:0;border-radius:7px;padding:11px 15px;background:#176b45;color:#fff;font-weight:bold;cursor:pointer}.btn.secondary{background:#315f91}.btn.warning{background:#a85b12}.actions{display:flex;gap:6px;flex-wrap:wrap}.actions button{padding:7px 9px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;margin-top:12px;min-width:600px}th,td{padding:10px;border:1px solid #dbe2ea;text-align:left}th{background:#12355b;color:#fff}.muted{color:#64748b;font-size:14px}.message{display:none;padding:12px;border-radius:8px;margin:12px 0}.message.success,.message.error{display:block}.message.success{background:#d9f2e4;color:#14532d}.message.error{background:#fee2e2;color:#991b1b}.pill{display:inline-block;border-radius:20px;padding:4px 9px;background:#e8eef6;font-size:12px}@media(max-width:650px){.card{padding:14px}.form{grid-template-columns:1fr}nav button{flex:1 1 42%}}
</style></head><body><header><h1>Gestion des niveaux et des classes</h1><div>Institution Mixte Clarodaro</div></header>
<nav><button type="button" onclick="location.href='PDG.html'">Tableau PDG</button><button type="button" onclick="location.href='index.html'">Élèves</button><button type="button" onclick="location.href='resultats.html'">Résultats</button><button type="button" onclick="location.href='annees-scolaires.html'">Année scolaire</button></nav>
<main class="container"><div id="message" class="message" role="status" aria-live="polite"></div>
<section class="card"><h2>Créer, modifier ou supprimer un niveau scolaire</h2><p class="muted">Exemples : Préscolaire, Fondamental 1er cycle, Secondaire. Les niveaux déjà utilisés ne sont jamais supprimés.</p><form id="levelForm" class="form"><label class="field">Code du niveau<input id="levelCode" maxlength="50" required placeholder="FOND-1"></label><label class="field">Nom du niveau<input id="levelName" maxlength="150" required placeholder="Fondamental 1er cycle"></label><label class="field">Description (facultatif)<input id="levelDescription" maxlength="500"></label><button class="btn" type="submit">Ajouter le niveau</button></form><div class="table-wrap"><table><thead><tr><th>Code</th><th>Niveau</th><th>Description</th><th>Action</th></tr></thead><tbody id="levelsBody"><tr><td colspan="4">Chargement…</td></tr></tbody></table></div></section>
<section class="card"><h2>Créer, modifier ou supprimer une classe</h2><p class="muted">Chaque classe est rattachée à un niveau. Archiver une classe la retire des nouvelles inscriptions ; ses inscriptions et ses résultats historiques restent conservés.</p><form id="classForm" class="form"><input id="classId" type="hidden"><label class="field">Code<input id="classCode" maxlength="50" required placeholder="FOND-1-A"></label><label class="field">Nom de la classe<input id="className" maxlength="150" required placeholder="1ère année fondamentale A"></label><label class="field">Niveau<select id="classLevel" required><option value="">Choisir un niveau</option></select></label><label class="field">Statut<select id="classStatus"><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option><option value="ARCHIVED">Archivée</option></select></label><div class="actions"><button class="btn" type="submit" id="saveClass">Enregistrer la classe</button><button class="btn secondary" type="button" id="cancelClass" hidden>Annuler</button></div></form></section>
<section class="card"><h2>Classes enregistrées dans PostgreSQL</h2><div class="table-wrap"><table><thead><tr><th>Code</th><th>Classe</th><th>Niveau</th><th>Statut</th><th>Actions</th></tr></thead><tbody id="classesBody"><tr><td colspan="5">Chargement…</td></tr></tbody></table></div></section></main>
<script src="/auth.js"></script><script>
"use strict";let structure={levels:[],classes:[]};
function message(t,k){const n=document.getElementById("message");n.textContent=t;n.className="message "+k;}
async function api(url,options={}){const r=await fetch(url,{credentials:"same-origin",headers:{"Accept":"application/json","Content-Type":"application/json",...(options.headers||{})},...options});let d={};try{d=await r.json();}catch(_){}if(!r.ok||!d.success)throw new Error(d.error||d.message||"Erreur serveur.");return d;}
function resetClassForm(){document.getElementById("classForm").reset();document.getElementById("classId").value="";document.getElementById("saveClass").textContent="Enregistrer la classe";document.getElementById("cancelClass").hidden=true;}
async function load(){const d=await api("/api/academic-structure/index.php?resource=classes");structure=d;const select=document.getElementById("classLevel");select.replaceChildren(new Option("Choisir un niveau",""));d.levels.forEach(x=>select.add(new Option(x.name+" ("+x.code+")",x.id)));const lb=document.getElementById("levelsBody");lb.replaceChildren();d.levels.forEach(x=>{const tr=document.createElement("tr");[x.code,x.name,x.description||"—"].forEach(v=>{const td=document.createElement("td");td.textContent=v;tr.appendChild(td);});const td=document.createElement("td"),actions=document.createElement("div");actions.className="actions";const b=document.createElement("button");b.className="btn secondary";b.textContent="Modifier";b.addEventListener("click",()=>editLevel(x));actions.appendChild(b);const del=document.createElement("button");del.className="btn warning";del.textContent="Supprimer";del.addEventListener("click",()=>deleteStructure("levels",x));actions.appendChild(del);td.appendChild(actions);tr.appendChild(td);lb.appendChild(tr);});if(!d.levels.length)lb.innerHTML='<tr><td colspan="4">Aucun niveau. Créez d’abord un niveau.</td></tr>';const cb=document.getElementById("classesBody");cb.replaceChildren();d.classes.forEach(x=>{const tr=document.createElement("tr");[x.code,x.name,x.level_name||"—"].forEach(v=>{const td=document.createElement("td");td.textContent=v;tr.appendChild(td);});const st=document.createElement("td"),pill=document.createElement("span");pill.className="pill";pill.textContent=x.status;st.appendChild(pill);tr.appendChild(st);const actions=document.createElement("td");actions.className="actions";const edit=document.createElement("button");edit.className="btn secondary";edit.textContent="Modifier";edit.addEventListener("click",()=>editClass(x));actions.appendChild(edit);const status=document.createElement("button");status.className=x.status==="ARCHIVED"?"btn":"btn warning";status.textContent=x.status==="ARCHIVED"?"Réactiver":"Archiver";status.addEventListener("click",()=>setStatus(x,x.status==="ARCHIVED"?"ACTIVE":"ARCHIVED"));actions.appendChild(status);const del=document.createElement("button");del.className="btn warning";del.textContent="Supprimer";del.addEventListener("click",()=>deleteStructure("classes",x));actions.appendChild(del);tr.appendChild(actions);cb.appendChild(tr);});if(!d.classes.length)cb.innerHTML='<tr><td colspan="5">Aucune classe enregistrée. Créez une classe après avoir créé son niveau.</td></tr>';select.disabled=!d.levels.length;}
async function deleteStructure(resource,x){
 const label=resource==="levels"?"le niveau":"la classe";
 if(!confirm("Supprimer définitivement "+label+" « "+x.name+" » ? Cette action n'est possible que si aucun élément ne dépend de cet enregistrement. Les données liées ne seront jamais supprimées."))return;
 try{
  await api("/api/academic-structure/index.php?resource="+resource+"&id="+encodeURIComponent(x.id),{method:"DELETE",body:JSON.stringify({resource})});
  if(resource==="classes"&&document.getElementById("classId").value===x.id)resetClassForm();
  await load();message((resource==="levels"?"Niveau":"Classe")+" supprimé(e).","success");
 }catch(e){message(e.message,"error");}
}
async function editLevel(x){const code=prompt("Code du niveau :",x.code);if(code===null)return;const name=prompt("Nom du niveau :",x.name);if(name===null)return;const description=prompt("Description :",x.description||"");if(description===null)return;try{await api("/api/academic-structure/index.php?resource=levels&id="+encodeURIComponent(x.id),{method:"PATCH",body:JSON.stringify({resource:"levels",code:code.trim(),name:name.trim(),description:description.trim()})});await load();message("Niveau modifié.","success");}catch(e){message(e.message,"error");}}
function editClass(x){document.getElementById("classId").value=x.id;document.getElementById("classCode").value=x.code;document.getElementById("className").value=x.name;document.getElementById("classLevel").value=x.level_id||"";document.getElementById("classStatus").value=x.status;document.getElementById("saveClass").textContent="Enregistrer les modifications";document.getElementById("cancelClass").hidden=false;document.getElementById("classForm").scrollIntoView({behavior:"smooth",block:"center"});}
async function setStatus(x,status){if(!confirm((status==="ARCHIVED"?"Archiver":"Réactiver")+" la classe « "+x.name+" » ? Les inscriptions et notes existantes seront conservées."))return;try{await api("/api/academic-structure/index.php?resource=classes&id="+encodeURIComponent(x.id),{method:"PATCH",body:JSON.stringify({resource:"classes",status})});await load();message("Statut mis à jour. Les données historiques sont conservées.","success");}catch(e){message(e.message,"error");}}
document.getElementById("levelForm").addEventListener("submit",async e=>{e.preventDefault();try{await api("/api/academic-structure/index.php?resource=levels",{method:"POST",body:JSON.stringify({resource:"levels",code:document.getElementById("levelCode").value.trim(),name:document.getElementById("levelName").value.trim(),description:document.getElementById("levelDescription").value.trim()})});e.target.reset();await load();message("Niveau ajouté dans PostgreSQL.","success");}catch(err){message(err.message,"error");}});
document.getElementById("classForm").addEventListener("submit",async e=>{e.preventDefault();const id=document.getElementById("classId").value;const body={resource:"classes",code:document.getElementById("classCode").value.trim(),name:document.getElementById("className").value.trim(),level_id:document.getElementById("classLevel").value,status:document.getElementById("classStatus").value};try{await api("/api/academic-structure/index.php?resource=classes"+(id?"&id="+encodeURIComponent(id):""),{method:id?"PATCH":"POST",body:JSON.stringify(body)});resetClassForm();await load();message(id?"Classe modifiée dans PostgreSQL.":"Classe ajoutée dans PostgreSQL.","success");}catch(err){message(err.message,"error");}});
document.getElementById("cancelClass").addEventListener("click",resetClassForm);
document.addEventListener("DOMContentLoaded",async()=>{try{const u=await IMCAuth.verifySession();if(!u||!IMCAuth.requirePermission("classes.manage")){location.replace("index.html");return;}await load();}catch(e){message(e.message,"error");}});
</script></body></html>
